// Snapshot (s2c, unreliable)
type Snapshot struct {
	Tick         uint32
	BaselineTick uint32
	AckInputSeq  uint32
	ServerTime   float64
	Self         SelfState
	Entities     []EntityRecord
	Removed      []uint32
}

func (*Snapshot) MsgID() uint8 { return 65 }

func (m *Snapshot) WriteBody(w *Writer) {
	w.U32(m.Tick)
	w.U32(m.BaselineTick)
	w.U32(m.AckInputSeq)
	w.F64(m.ServerTime)
	m.Self.Write(w)
	w.U16(uint16(len(m.Entities)))
	for i0 := range m.Entities {
		m.Entities[i0].Write(w)
	}
	w.U16(uint16(len(m.Removed)))
	for i0 := range m.Removed {
		w.U32(m.Removed[i0])
	}
}

func (m *Snapshot) ReadBody(r *Reader) {
	m.Tick = r.U32()
	m.BaselineTick = r.U32()
	m.AckInputSeq = r.U32()
	m.ServerTime = r.F64()
	m.Self.Read(r)
	{
		n0 := r.Count()
		m.Entities = make([]EntityRecord, n0)
		for i0 := 0; i0 < n0; i0++ {
			m.Entities[i0].Read(r)
		}
	}
	{
		n0 := r.Count()
		m.Removed = make([]uint32, n0)
		for i0 := 0; i0 < n0; i0++ {
			m.Removed[i0] = r.U32()
		}
	}
}

func (m *Snapshot) ToJSON() map[string]any {
	out := map[string]any{}
	out["tick"] = m.Tick
	out["baselineTick"] = m.BaselineTick
	out["ackInputSeq"] = m.AckInputSeq
	out["serverTime"] = m.ServerTime
	out["self"] = m.Self.ToJSON()
	out["entities"] = func() []any {
		out := make([]any, len(m.Entities))
		for j0 := range m.Entities {
			out[j0] = m.Entities[j0].ToJSON()
		}
		return out
	}()
	out["removed"] = func() []any {
		out := make([]any, len(m.Removed))
		for j0 := range m.Removed {
			out[j0] = m.Removed[j0]
		}
		return out
	}()
	return out
}

