// Event (s2c, reliable): Generic gameplay event (damage number, discovery, ignite, loot...). Kinds are defined by the owning package in contracts/events.md.
type Event struct {
	Kind     uint16
	EntityID uint32
	TargetID uint32
	Value    int32
	X        int32
	Y        int32
	Z        int32
	Data     []byte
}

func (*Event) MsgID() uint8 { return 67 }

func (m *Event) WriteBody(w *Writer) {
	w.U16(m.Kind)
	w.U32(m.EntityID)
	w.U32(m.TargetID)
	w.I32(m.Value)
	w.I32(m.X)
	w.I32(m.Y)
	w.I32(m.Z)
	w.Bytes(m.Data)
}

func (m *Event) ReadBody(r *Reader) {
	m.Kind = r.U16()
	m.EntityID = r.U32()
	m.TargetID = r.U32()
	m.Value = r.I32()
	m.X = r.I32()
	m.Y = r.I32()
	m.Z = r.I32()
	m.Data = r.Bytes()
}

func (m *Event) ToJSON() map[string]any {
	out := map[string]any{}
	out["kind"] = m.Kind
	out["entityId"] = m.EntityID
	out["targetId"] = m.TargetID
	out["value"] = m.Value
	out["x"] = m.X
	out["y"] = m.Y
	out["z"] = m.Z
	out["data"] = hex.EncodeToString(m.Data)
	return out
}

// WorldEdits (s2c, chunk): Active edits for a chunk on first interest, then live deltas (list of one).
