// NewMessage returns an empty message for an id, or nil if unknown.
func NewMessage(id uint8) Message {
	switch id {
	case 1:
		return &Hello{}
	case 2:
		return &Input{}
	case 3:
		return &ClockPing{}
	case 4:
		return &HitClaim{}
	case 5:
		return &Interact{}
	case 6:
		return &Bye{}
	case 64:
		return &Welcome{}
	case 65:
		return &Snapshot{}
	case 66:
		return &ClockPong{}
	case 67:
		return &Event{}
	case 68:
		return &WorldEdits{}
	case 69:
		return &Kick{}
	case 70:
		return &HitResult{}
	case 71:
		return &SaveBlob{}
	case 72:
		return &ZoneTransfer{}
	}
	return nil
}

// MessageName returns the protocol.yaml name for an id.
func MessageName(id uint8) string {
	switch id {
	case 1:
		return "Hello"
	case 2:
		return "Input"
	case 3:
		return "ClockPing"
	case 4:
		return "HitClaim"
	case 5:
		return "Interact"
	case 6:
		return "Bye"
	case 64:
		return "Welcome"
	case 65:
		return "Snapshot"
	case 66:
		return "ClockPong"
	case 67:
		return "Event"
	case 68:
		return "WorldEdits"
	case 69:
		return "Kick"
	case 70:
		return "HitResult"
	case 71:
		return "SaveBlob"
	case 72:
		return "ZoneTransfer"
	}
	return fmt.Sprintf("unknown(%d)", id)
}
